      if ('agentContextId' in value) throw new ApplicationError('invalid-input', `Choose a canvas for ${name}.`);
      return { documentId: value.documentId, ...(value.viewId ? { viewId: value.viewId } : {}), checkpointId: value.checkpointId };
    };
